export interface DiscoveredReport { id:string; companyId:string; title:string; url:string; reportDate:string|null; periodEnd:string|null; sourceType:'ANNUAL_REPORT'|'QUARTERLY_REPORT'; discoveredAt:string; status:'DISCOVERED'|'PROCESSED'|'IGNORED'|'FAILED' }
const htmlDecode=(s:string)=>s.replace(/&#39;/g,"'").replace(/&quot;/g,'"').replace(/&amp;/g,'&').replace(/&nbsp;/g,' ')
export function parseSanoReports(html:string): DiscoveredReport[] { const out:DiscoveredReport[]=[]; const re=/<a[^>]+href=["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi; let m:RegExpExecArray|null; while((m=re.exec(html))){const title=htmlDecode(m[2].replace(/<[^>]+>/g,'').replace(/\s+/g,' ').trim()); if(!/(דוח|דו.?ח|report)/i.test(title)) continue; const href=m[1].startsWith('http')?m[1]:new URL(m[1],'https://www.sano.co.il').href; const year=title.match(/20\d{2}/)?.[0]??null; const quarter=title.match(/(ראשון|שני|שלישי|רביעי|Q[1-4])/i)?.[0]??null; out.push({id:`sano-discovered-${btoa(href).replace(/[^a-z0-9]/gi,'').slice(0,32)}`,companyId:'sano',title,url:href,reportDate:null,periodEnd:year?`${year}-${quarter?'06':'12'}-31`:null,sourceType:quarter?'QUARTERLY_REPORT':'ANNUAL_REPORT',discoveredAt:new Date().toISOString(),status:'DISCOVERED'}); } return [...new Map(out.map((x)=>[x.url,x])).values()] }
export async function discoverSano(fetcher:typeof fetch):Promise<DiscoveredReport[]> { const response=await fetcher('https://www.sano.co.il/company/%D7%93%D7%95%D7%97%D7%95%D7%AA-%D7%9B%D7%A1%D7%A4%D7%99%D7%99%D7%9D/'); if(!response.ok) throw new Error(`Sano IR returned ${response.status}`); return parseSanoReports(await response.text()) }
